import type { ClockPorts } from './model.ts';

export function createActiveClock(
  ports: ClockPorts, advance: (milliseconds: number) => void, nextDelay: () => number | null,
) {
  let connected = false;
  let hidden = ports.isHidden();
  let previous = ports.now();
  let generation = 0;
  let cancelTimer: (() => void) | null = null;
  let stopWatching: (() => void) | null = null;

  function sample(): void {
    const current = ports.now();
    if (connected && !hidden) advance(Math.max(0, current - previous));
    previous = current;
  }

  function refresh(): void {
    generation += 1;
    cancelTimer?.();
    cancelTimer = null;
    const delay = nextDelay();
    if (!connected || hidden || delay === null) return;
    const expectedGeneration = generation;
    cancelTimer = ports.schedule(() => {
      if (!connected || generation !== expectedGeneration) return;
      sample();
      refresh();
    }, delay);
  }

  function reset(): void {
    previous = ports.now();
    refresh();
  }

  function connect(): () => void {
    connected = true;
    hidden = ports.isHidden();
    previous = ports.now();
    stopWatching = ports.watchVisibility(() => {
      sample();
      hidden = ports.isHidden();
      refresh();
    });
    refresh();
    return () => {
      sample();
      connected = false;
      generation += 1;
      cancelTimer?.();
      stopWatching?.();
      cancelTimer = null;
      stopWatching = null;
    };
  }

  return { sample, refresh, reset, connect };
}
import type { GameState } from '../state.ts';

export interface Announcement {
  readonly id: number;
  readonly text: string;
}

export interface SessionView {
  readonly game: GameState;
  readonly paused: boolean;
  readonly celebrate: boolean;
  readonly revision: number;
  readonly best: number | null;
  readonly announcement: Announcement | null;
  readonly loadStatus: string;
}

export interface ClockPorts {
  readonly now: () => number;
  readonly isHidden: () => boolean;
  readonly schedule: (callback: () => void, delay: number) => () => void;
  readonly watchVisibility: (callback: () => void) => () => void;
}
import { isSide, SIDES } from '../boardCode.ts';
import type { Side } from '../boardCode.ts';
import { isRecord } from '../json.ts';
import { MAX_MOVES } from '../state.ts';

export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export interface Preferences {
  readonly size: Side;
  readonly best: Readonly<Partial<Record<Side, number>>>;
}
export interface PreferenceStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}
export type StorageAccess = () => PreferenceStorage | null;
const browserStorage: StorageAccess = () => globalThis.localStorage;

export function readPreferences(access: StorageAccess = browserStorage): Preferences {
  const defaults: Preferences = { size: 4, best: {} };
  try {
    const text = access()?.getItem(PREFERENCES_KEY);
    if (!text) return defaults;
    const value: unknown = JSON.parse(text);
    if (!isRecord(value) || value.version !== 1) return defaults;
    const best: Partial<Record<Side, number>> = {};
    if (isRecord(value.best)) {
      for (const size of SIDES) {
        const score = value.best[String(size)];
        if (typeof score === 'number' && Number.isSafeInteger(score) && score >= 0
          && score <= MAX_MOVES) best[size] = score;
      }
    }
    return { size: isSide(value.size) ? value.size : 4, best };
  } catch { return defaults; }
}

export function writePreferences(
  preferences: Preferences, access: StorageAccess = browserStorage,
): void {
  try { access()?.setItem(PREFERENCES_KEY, JSON.stringify({ version: 1, ...preferences })); }
  catch { /* Saving is optional; the in-memory session remains playable. */ }
}
import { MAX_SEED } from '../boardCode.ts';
import type { ClockPorts } from './model.ts';

export function freshSeed(previous?: number): number {
  const words = new Uint32Array(1);
  let random: number;
  try { random = (globalThis.crypto.getRandomValues(words)[0] ?? 0) % MAX_SEED + 1; }
  catch { random = Math.floor(Math.random() * MAX_SEED) + 1; }
  return random === previous ? random % MAX_SEED + 1 : random;
}

export const browserClock: ClockPorts = {
  now: () => performance.now(),
  isHidden: () => document.hidden,
  schedule(callback, delay) {
    const timer = window.setTimeout(callback, delay);
    return () => window.clearTimeout(timer);
  },
  watchVisibility(callback) {
    document.addEventListener('visibilitychange', callback);
    return () => document.removeEventListener('visibilitychange', callback);
  },
};
import { isWon } from '../state.ts';
import type { GameState } from '../state.ts';
import { formatTime } from './formatTime.ts';

export function turnAnnouncement(before: GameState, after: GameState): string | null {
  if (before === after || before.selection.kind !== 'one') return null;
  if (after.selection.kind === 'mismatch') return 'No match. Cards close after a short pause.';
  if (after.matched.length === before.matched.length) return null;
  if (isWon(after)) {
    return `Pair found. All pairs found in ${after.moves} moves and ${formatTime(after.elapsedMs)}.`;
  }
  const pairs = after.matched.length / 2;
  return pairs === 1 ? 'Pair found. 1 pair matched.' : `Pair found. ${pairs} pairs matched.`;
}

