import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';
import { Card } from './Card.tsx';
import { Face } from './Face.tsx';
import { faceIdentity } from './faceIdentity.ts';

describe('face artwork and hidden card privacy', () => {
  it('names the documented identities and keeps every identity distinct without color', () => {
    expect(faceIdentity(0).name).toBe('cyan solid circle, marker top');
    expect(faceIdentity(64).name).toBe('cyan outline circle, marker top');
    expect(faceIdentity(127).name).toBe('ice outline chevron, marker top-left');
    const identities = Array.from({ length: 128 }, (_, id) => faceIdentity(id));
    expect(new Set(identities.map((face) => [face.path, face.fill, face.markerX, face.markerY].join('|'))).size)
      .toBe(128);
    for (const face of identities) expect(Math.hypot(face.markerX - 50, face.markerY - 50)).toBeCloseTo(40);
  });

  it('renders diagonal markers last, with a separating stroke and the required SVG geometry', () => {
    const markup = renderToStaticMarkup(<Face id={73} />);
    expect(markup).toContain('viewBox="0 0 100 100"');
    expect(markup).toContain('fill="none"');
    expect(markup).toContain('stroke-width="5"');
    expect(markup).toContain('r="5"');
    expect(markup).toContain('stroke="#111625" stroke-width="3"');
    expect(markup.indexOf('<circle')).toBeGreaterThan(markup.indexOf('<path'));
  });

  it('makes hidden DOM identical across faces and adds identity only when exposed', () => {
    const render = (face: number, state: 'closed' | 'revealed' | 'matched') => renderToStaticMarkup(
      <Card index={0} size={4} face={face} state={state} tabIndex={0} blocked={false} ref={null}
        onActivate={() => {}} onFocus={() => {}} onKeyDown={() => {}} />,
    );
    expect(render(0, 'closed')).toBe(render(127, 'closed'));
    expect(render(127, 'closed')).toContain('Row 1, column 1, closed');
    expect(render(0, 'revealed')).toContain('Row 1, column 1, cyan solid circle, marker top, revealed');
    expect(render(0, 'matched')).toContain('aria-disabled="true"');
    expect(render(0, 'matched')).toContain('✓');
  });
});
import { describe, expect, it } from 'vitest';
import { parseBoardCode, SIDES } from './boardCode.ts';
import { generateDeck, nextRandomState } from './deck.ts';

function deck(code: string): readonly number[] {
  const board = parseBoardCode(code);
  if (!board) throw new Error('Invalid fixture.');
  return generateDeck(board);
}

describe('np1 board codes and independent generation vectors', () => {
  it('matches the published Park–Miller states', () => {
    let state = 1;
    const actual = Array.from({ length: 5 }, () => {
      state = nextRandomState(state);
      return state;
    });
    expect(actual).toEqual([16807, 282475249, 1622650073, 984943658, 1144108930]);
  });

  it('matches the published seed-1 deal and a Python integer-arithmetic vector', () => {
    expect(deck('np1-4-1')).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]);
    expect(deck('np1-4-2147483646')).toEqual([6, 7, 2, 4, 5, 0, 3, 1, 0, 7, 5, 4, 6, 2, 1, 3]);
  });

  it('rejects a biased shuffle draw before using its next generator state', () => {
    // Python modular inverse selected this seed: its first state is 2147483646.
    expect(nextRandomState(739806647)).toBe(2147483646);
    expect(deck('np1-4-739806647')).toEqual([6, 7, 2, 4, 5, 0, 3, 1, 0, 7, 5, 4, 6, 2, 1, 3]);
  });

  it.each(SIDES)('creates exactly two of each face at size %i', (size) => {
    const cards = deck(`np1-${size}-987654321`);
    expect(cards).toHaveLength(size * size);
    expect(Object.isFrozen(cards)).toBe(true);
    for (let face = 0; face < size * size / 2; face += 1) {
      expect(cards.filter((card) => card === face)).toHaveLength(2);
    }
    expect(cards).toEqual(deck(`np1-${size}-987654321`));
  });

  it.each([
    '', 'np2-4-1', 'np1-04-1', 'np1-5-1', 'np1-4-0', 'np1-4-01',
    'np1-4--1', 'np1-4-1.0', 'np1-4-2147483647', 'np1-4-1e2',
    ' np1-4-1', 'np1-4-1 ', 'np1-4-1\n', 'np1-4-1\r\n',
  ])('rejects noncanonical code %j', (code) => {
    expect(parseBoardCode(code)).toBeNull();
  });
});
import { describe, expect, it } from 'vitest';
import { SIDES } from '../boardCode.ts';
import { focusDestination, isMovementKey } from './navigation.ts';

describe('board keyboard movement', () => {
  it.each(SIDES)('moves one row or column at size %i without wrapping', (size) => {
    expect(focusDestination(0, size, 'ArrowLeft')).toBe(0);
    expect(focusDestination(0, size, 'ArrowUp')).toBe(0);
    expect(focusDestination(size - 1, size, 'ArrowRight')).toBe(size - 1);
    expect(focusDestination(size * size - 1, size, 'ArrowDown')).toBe(size * size - 1);
    expect(focusDestination(size, size, 'ArrowLeft')).toBe(size);
    expect(focusDestination(size + 1, size, 'ArrowLeft')).toBe(size);
    expect(focusDestination(size + 1, size, 'ArrowRight')).toBe(size + 2);
    expect(focusDestination(size + 1, size, 'ArrowUp')).toBe(1);
    expect(focusDestination(size + 1, size, 'ArrowDown')).toBe(size * 2 + 1);
  });

  it('recognizes only the four supported movement keys', () => {
    for (const key of ['Home', 'End', 'PageDown', 'Tab', 'Enter', ' ', 'a']) {
      expect(isMovementKey(key)).toBe(false);
    }
    for (const key of ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']) {
      expect(isMovementKey(key)).toBe(true);
    }
  });
});
