    expect(replayGame(replay(changes))).toBeNull();
  });

  it('rejects malformed and oversized JSON', () => {
    for (const invalid of ['', '{', 'null', '{}', '[]', ' '.repeat(REPLAY_BYTE_LIMIT) + replay()]) {
