import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { viteSingleFile } from 'vite-plugin-singlefile';

export default defineConfig({
  plugins: [react(), viteSingleFile()],
  build: { target: 'es2023', assetsInlineLimit: 1000000, cssCodeSplit: false },
});
import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: { include: ['src/**/*.test.ts', 'src/**/*.test.tsx'], environment: 'node' },
});

export const SIDES = [4, 6, 8, 10, 12, 14, 16] as const;
export type Side = (typeof SIDES)[number];
export const MAX_SEED = 2147483646;
export const BOARD_VERSION = 'np1';

export interface BoardDescription {
  readonly code: string;
  readonly size: Side;
  readonly seed: number;
}

export function isSide(value: unknown): value is Side {
  return SIDES.some((size) => size === value);
}

export function parseBoardCode(code: string): BoardDescription | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code);
  if (!match || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isSide(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}
import type { BoardDescription } from './boardCode.ts';

const MODULUS = 2147483647;
const MULTIPLIER = 16807;
const GENERATOR_VALUES = MODULUS - 1;

export function nextRandomState(state: number): number {
  return (state * MULTIPLIER) % MODULUS;
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, i) => Math.floor(i / 2));
  let randomState = board.seed;
  for (let i = deck.length - 1; i > 0; i -= 1) {
    const possibilities = i + 1;
    const limit = Math.floor(GENERATOR_VALUES / possibilities) * possibilities;
    let draw: number;
    do {
      randomState = nextRandomState(randomState);
      draw = randomState - 1;
    } while (draw >= limit);
    const j = draw % possibilities;
    const atI = deck[i];
    const atJ = deck[j];
    if (atI === undefined || atJ === undefined) throw new Error('Invalid shuffle index.');
    deck[i] = atJ;
    deck[j] = atI;
  }
  return Object.freeze(deck);
