import { useImperativeHandle, useRef, useState } from 'react';
import type { KeyboardEvent, Ref } from 'react';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import type { CardState } from './Card.tsx';
import { focusDestination, isMovementKey } from './navigation.ts';
import './Board.css';

export interface BoardHandle { focusRemembered(): void }
export interface BoardProps {
  readonly game: GameState;
  readonly paused: boolean;
  readonly ref: Ref<BoardHandle>;
  readonly onActivate: (index: number) => void;
}

export function Board({ game, paused, ref, onActivate }: BoardProps) {
  const [remembered, setRemembered] = useState(0);
  const cards = useRef(new Map<number, HTMLButtonElement>());
  useImperativeHandle(ref, () => ({ focusRemembered: () => cards.current.get(remembered)?.focus() }), [remembered]);

  function move(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || !isMovementKey(event.key)) return;
    event.preventDefault();
    cards.current.get(focusDestination(index, game.board.size, event.key))?.focus();
  }

  function cardState(index: number): CardState {
    if (game.matched.includes(index)) return 'matched';
    switch (game.selection.kind) {
      case 'closed': return 'closed';
      case 'one': return game.selection.index === index ? 'revealed' : 'closed';
      case 'mismatch':
        return game.selection.first === index || game.selection.second === index ? 'revealed' : 'closed';
    }
  }

  return (
    <section aria-label="Card board" aria-describedby="board-help" className="board-section">
      <div className="board-scroll">
        <div className="board-grid" style={{ gridTemplateColumns: `repeat(${game.board.size}, minmax(44px, 88px))`,
          minWidth: game.board.size * 44 + (game.board.size - 1) * 6 }}>
          {game.deck.map((face, index) => (
            <Card key={index} index={index} size={game.board.size} face={face} state={cardState(index)}
              tabIndex={remembered === index ? 0 : -1} blocked={paused || game.selection.kind === 'mismatch'}
              ref={(button) => { if (button) cards.current.set(index, button); else cards.current.delete(index); }}
              onActivate={() => onActivate(index)} onKeyDown={(event) => move(event, index)}
              onFocus={() => {
                setRemembered(index);
                cards.current.get(index)?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
              }} />
          ))}
        </div>
      </div>
      <p id="board-help" className="help board-help">Reveal two cards to find a pair. Use arrow keys to move, Enter or Space to reveal.</p>
    </section>
  );
}

/work/src/game/board/navigation.ts.content:
export const MOVEMENT_KEYS = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'] as const;
export type MovementKey = (typeof MOVEMENT_KEYS)[number];

export function isMovementKey(key: string): key is MovementKey {
  return MOVEMENT_KEYS.some((movement) => movement === key);
}

export function focusDestination(index: number, size: number, key: MovementKey): number {
  const row = Math.floor(index / size);
  const column = index % size;
  switch (key) {
    case 'ArrowLeft': return column > 0 ? index - 1 : index;
    case 'ArrowRight': return column < size - 1 ? index + 1 : index;
    case 'ArrowUp': return row > 0 ? index - size : index;
    case 'ArrowDown': return row < size - 1 ? index + size : index;
  }
}

/work/src/game/board/faceIdentity.ts.content:
export const SHAPES = [
  { name: 'circle', path: 'M75 50a25 25 0 1 1-50 0a25 25 0 1 1 50 0Z' },
  { name: 'square', path: 'M25 25H75V75H25Z' },
  { name: 'triangle', path: 'M50 25L75 75H25Z' },
  { name: 'diamond', path: 'M50 25L75 50L50 75L25 50Z' },
  { name: 'star', path: 'M50 25L56 42L74 42L60 53L65 73L50 61L35 73L40 53L26 42L44 42Z' },
  { name: 'hexagon', path: 'M37.5 25H62.5L75 50L62.5 75H37.5L25 50Z' },
  { name: 'plus', path: 'M42 25H58V42H75V58H58V75H42V58H25V42H42Z' },
  { name: 'chevron', path: 'M25 25H44L75 50L44 75H25L56 50Z' },
] as const;

export const PALETTE = [
  { name: 'cyan', color: '#63E7FF' }, { name: 'magenta', color: '#FF71D6' },
  { name: 'green', color: '#8BEA7D' }, { name: 'yellow', color: '#FFE082' },
  { name: 'orange', color: '#FFB064' }, { name: 'violet', color: '#B49AFF' },
  { name: 'rose', color: '#FF8296' }, { name: 'ice', color: '#D9F3FF' },
] as const;

const DIAGONAL = 40 / Math.sqrt(2);
export const MARKERS = [
  { name: 'top', x: 0, y: -40 }, { name: 'top-right', x: DIAGONAL, y: -DIAGONAL },
  { name: 'right', x: 40, y: 0 }, { name: 'bottom-right', x: DIAGONAL, y: DIAGONAL },
  { name: 'bottom', x: 0, y: 40 }, { name: 'bottom-left', x: -DIAGONAL, y: DIAGONAL },
  { name: 'left', x: -40, y: 0 }, { name: 'top-left', x: -DIAGONAL, y: -DIAGONAL },
] as const;
export const FILLS = ['solid', 'outline'] as const;

export function faceIdentity(id: number) {
  if (!Number.isInteger(id) || id < 0 || id > 127) throw new Error('Invalid face identity.');
  const shape = SHAPES[id % 8];
  const markerIndex = Math.floor(id / 8) % 8;
  const marker = MARKERS[markerIndex];
  const palette = PALETTE[markerIndex];
  const fill = FILLS[Math.floor(id / 64)];
  if (!shape || !marker || !palette || !fill) throw new Error('Invalid face parts.');
  return {
    path: shape.path, color: palette.color, fill,
    markerX: 50 + marker.x, markerY: 50 + marker.y,
    name: `${palette.name} ${fill} ${shape.name}, marker ${marker.name}`,
  };
}

