export const SIDES = [4, 6, 8, 10, 12, 14, 16] as const;
export type Side = (typeof SIDES)[number];
export const MAX_SEED = 2147483646;
export const BOARD_VERSION = 'np1';

export interface BoardDescription {
  readonly code: string;
  readonly size: Side;
  readonly seed: number;
}

export function isSide(value: unknown): value is Side {
  return SIDES.some((size) => size === value);
}

export function parseBoardCode(code: string): BoardDescription | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code);
  if (!match || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isSide(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}
import type { BoardDescription } from './boardCode.ts';

const MODULUS = 2147483647;
const MULTIPLIER = 16807;
const GENERATOR_VALUES = MODULUS - 1;

export function nextRandomState(state: number): number {
  return (state * MULTIPLIER) % MODULUS;
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, i) => Math.floor(i / 2));
  let randomState = board.seed;
  for (let i = deck.length - 1; i > 0; i -= 1) {
    const possibilities = i + 1;
    const limit = Math.floor(GENERATOR_VALUES / possibilities) * possibilities;
    let draw: number;
    do {
      randomState = nextRandomState(randomState);
      draw = randomState - 1;
    } while (draw >= limit);
    const j = draw % possibilities;
    const atI = deck[i];
    const atJ = deck[j];
    if (atI === undefined || atJ === undefined) throw new Error('Invalid shuffle index.');
    deck[i] = atJ;
    deck[j] = atI;
  }
  return Object.freeze(deck);
}
import { parseBoardCode } from './boardCode.ts';
import type { BoardDescription } from './boardCode.ts';
import { generateDeck } from './deck.ts';

export const SELECTION_KINDS = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export const MISMATCH_MS = 800;
export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;

export type Selection =
  | { readonly kind: typeof SELECTION_KINDS.closed }
  | { readonly kind: typeof SELECTION_KINDS.one; readonly index: number }
  | {
    readonly kind: typeof SELECTION_KINDS.mismatch;
    readonly first: number;
    readonly second: number;
    readonly remainingMs: number;
  };

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return {
    board,
    deck: generateDeck(board),
    matched: [],
    selection: { kind: SELECTION_KINDS.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}
import { isWon, MAX_MOVES, MISMATCH_MS, SELECTION_KINDS } from './state.ts';
import type { GameState } from './state.ts';

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length
    || state.matched.includes(index) || isWon(state)) return state;
  switch (state.selection.kind) {
    case SELECTION_KINDS.mismatch:
      return state;
    case SELECTION_KINDS.closed:
      return { ...state, started: true, selection: { kind: SELECTION_KINDS.one, index } };
    case SELECTION_KINDS.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.deck[first] === state.deck[index]) {
        return {
          ...state, moves, matched: [...state.matched, first, index],
          selection: { kind: SELECTION_KINDS.closed },
        };
      }
      return {
        ...state, moves,
        selection: { kind: SELECTION_KINDS.mismatch, first, second: index, remainingMs: MISMATCH_MS },
      };
    }
  }
}
import { isWon, MAX_ELAPSED_MS, SELECTION_KINDS } from './state.ts';
import type { GameState, Selection } from './state.ts';

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!state.started || isWon(state) || !Number.isFinite(milliseconds) || milliseconds <= 0) return state;
  let selection: Selection;
  switch (state.selection.kind) {
    case SELECTION_KINDS.closed:
    case SELECTION_KINDS.one:
      selection = state.selection;
      break;
    case SELECTION_KINDS.mismatch:
      selection = milliseconds >= state.selection.remainingMs
        ? { kind: SELECTION_KINDS.closed }
        : { ...state.selection, remainingMs: state.selection.remainingMs - milliseconds };
      break;
