    cancelTimer = ports.schedule(() => {
      if (!connected || generation !== expectedGeneration) return;
      sample();
      refresh();
    }, delay);
  }

  function reset(): void {
    previous = ports.now();
    refresh();
  }

  function connect(): () => void {
    connected = true;
    hidden = ports.isHidden();
    previous = ports.now();
    stopWatching = ports.watchVisibility(() => {
      sample();
      hidden = ports.isHidden();
      refresh();
    });
    refresh();
    return () => {
      sample();
      connected = false;
      generation += 1;
      cancelTimer?.();
      stopWatching?.();
      cancelTimer = null;
      stopWatching = null;
    };
  }

