import type { ClockPorts } from './model.ts';

export function createActiveClock(
  ports: ClockPorts, advance: (milliseconds: number) => void, nextDelay: () => number | null,
) {
  let connected = false;
  let hidden = ports.isHidden();
  let previous = ports.now();
  let generation = 0;
  let cancelTimer: (() => void) | null = null;
  let stopWatching: (() => void) | null = null;

  function sample(): void {
    const current = ports.now();
    if (connected && !hidden) advance(Math.max(0, current - previous));
    previous = current;
  }

  function refresh(): void {
    generation += 1;
    cancelTimer?.();
    cancelTimer = null;
    const delay = nextDelay();
    if (!connected || hidden || delay === null) return;
    const expectedGeneration = generation;
    cancelTimer = ports.schedule(() => {
      if (!connected || generation !== expectedGeneration) return;
      sample();
      refresh();
    }, delay);
  }

  function reset(): void {
    previous = ports.now();
    refresh();
  }

  function connect(): () => void {
    connected = true;
    hidden = ports.isHidden();
    previous = ports.now();
    stopWatching = ports.watchVisibility(() => {
      sample();
      hidden = ports.isHidden();
      refresh();
    });
    refresh();
    return () => {
      sample();
      connected = false;
      generation += 1;
      cancelTimer?.();
      stopWatching?.();
      cancelTimer = null;
      stopWatching = null;
    };
  }

  return { sample, refresh, reset, connect };
}
import { useImperativeHandle, useRef, useState } from 'react';
import type { KeyboardEvent, Ref } from 'react';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import type { CardState } from './Card.tsx';
import { focusDestination, isMovementKey } from './navigation.ts';
import './Board.css';

export interface BoardHandle { focusRemembered(): void }
export interface BoardProps {
  readonly game: GameState;
  readonly paused: boolean;
  readonly ref: Ref<BoardHandle>;
  readonly onActivate: (index: number) => void;
}

export function Board({ game, paused, ref, onActivate }: BoardProps) {
  const [remembered, setRemembered] = useState(0);
  const cards = useRef(new Map<number, HTMLButtonElement>());
  useImperativeHandle(ref, () => ({ focusRemembered: () => cards.current.get(remembered)?.focus() }), [remembered]);

  function move(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || !isMovementKey(event.key)) return;
    event.preventDefault();
    cards.current.get(focusDestination(index, game.board.size, event.key))?.focus();
  }

  function cardState(index: number): CardState {
    if (game.matched.includes(index)) return 'matched';
    switch (game.selection.kind) {
      case 'closed': return 'closed';
      case 'one': return game.selection.index === index ? 'revealed' : 'closed';
      case 'mismatch':
        return game.selection.first === index || game.selection.second === index ? 'revealed' : 'closed';
    }
  }

  return (
    <section aria-label="Card board" aria-describedby="board-help" className="board-section">
      <div className="board-scroll">
        <div className="board-grid" style={{ gridTemplateColumns: `repeat(${game.board.size}, minmax(44px, 88px))`,
          minWidth: game.board.size * 44 + (game.board.size - 1) * 6 }}>
          {game.deck.map((face, index) => (
            <Card key={index} index={index} size={game.board.size} face={face} state={cardState(index)}
              tabIndex={remembered === index ? 0 : -1} blocked={paused || game.selection.kind === 'mismatch'}
              ref={(button) => { if (button) cards.current.set(index, button); else cards.current.delete(index); }}
              onActivate={() => onActivate(index)} onKeyDown={(event) => move(event, index)}
              onFocus={() => {
                setRemembered(index);
                cards.current.get(index)?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
              }} />
          ))}
        </div>
      </div>
      <p id="board-help" className="help board-help">Reveal two cards to find a pair. Use arrow keys to move, Enter or Space to reveal.</p>
    </section>
  );
}
import type { KeyboardEvent, Ref } from 'react';
import { Face } from './Face.tsx';
import { faceIdentity } from './faceIdentity.ts';
import './Card.css';

export const CARD_STATES = ['closed', 'revealed', 'matched'] as const;
export type CardState = (typeof CARD_STATES)[number];
export interface CardProps {
  readonly index: number;
  readonly size: number;
  readonly face: number;
  readonly state: CardState;
  readonly tabIndex: number;
  readonly blocked: boolean;
  readonly ref: Ref<HTMLButtonElement>;
  readonly onActivate: () => void;
  readonly onFocus: () => void;
  readonly onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
}

export function Card(props: CardProps) {
  const { index, size, face, state, tabIndex, blocked, ref, onActivate, onFocus, onKeyDown } = props;
  const position = `Row ${Math.floor(index / size) + 1}, column ${index % size + 1}`;
  const name = state === 'closed' ? `${position}, closed` : `${position}, ${faceIdentity(face).name}, ${state}`;
  return (
    <button type="button" className={`card card--${state}`} ref={ref} tabIndex={tabIndex}
      aria-label={name} aria-disabled={state === 'matched' || blocked ? true : undefined}
      onFocus={onFocus} onKeyDown={onKeyDown}
      onClick={(event) => {
        if (event.button === 0 && !event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey) onActivate();
      }}>
      {state === 'closed' ? (
        <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" className="card-back">
          <path d="M50 34L66 50L50 66L34 50Z" fill="none" stroke="currentColor" strokeWidth="3" />
        </svg>
      ) : <Face id={face} />}
      {state === 'matched' && <span className="card-check" aria-hidden="true">✓</span>}
    </button>
  );
}
import type { Announcement } from '../session/model.ts';

export interface LiveAnnouncementProps { readonly event: Announcement | null }

export function LiveAnnouncement({ event }: LiveAnnouncementProps) {
  return (
